// === STORE-AND-LOOKUP (Two Sum pattern) ===
function storeAndLookup(arr, target) {
  const seen = new Map(); // stores value → index (or value → true for existence)
  for (let i = 0; i < arr.length; i++) {
    const complement = target - arr[i];
    if (seen.has(complement)) return [seen.get(complement), i];
    seen.set(arr[i], i); // store AFTER checking to avoid using same element twice
  }
  return [];
}

// === PREFIX SUM + HASHMAP (subarray sum = k) ===
function subarraySum(arr, k) {
  const prefixCount = new Map([[0, 1]]); // empty prefix has sum 0, seen once
  let count = 0, prefix = 0;
  for (const x of arr) {
    prefix += x;
    // look up: how many prefixes equal (current - k)?
    count += prefixCount.get(prefix - k) || 0;
    // store current prefix
    prefixCount.set(prefix, (prefixCount.get(prefix) || 0) + 1);
  }
  return count;
}
